 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [row[:] for row in grid]
    for dr in (-1, 1):
        for dc in (-1, 1):
            # Scan each diagonal run; extend runs of length >= 2 through background.
            for r in range(h):
                for c in range(w):
                    v = grid[r][c]
                    if v == bg:
                        continue
                    pr, pc = r-dr, c-dc
                    if 0 <= pr < h and 0 <= pc < w and grid[pr][pc] == v:
                        continue
                    rr, cc = r, c
                    length = 1
                    while 0 <= rr+dr < h and 0 <= cc+dc < w and grid[rr+dr][cc+dc] == v:
                        rr += dr; cc += dc; length += 1
                    if length < 2:
                        continue
                    for sr, sc, step in ((r, c, -1), (rr, cc, 1)):
                        y, x = sr + step*dr, sc + step*dc
                        while 0 <= y < h and 0 <= x < w and grid[y][x] == bg:
                            out[y][x] = v
                            y += step*dr; x += step*dc
    return out
